import pypdf

reader = pypdf.PdfReader("/root/sc100-blank.pdf")
fields = reader.get_fields()

if fields:
    for field_name, value in fields.items():
        print(f"Field: {field_name}, Type: {value.get('/FT')}")
else:
    print("No fields found.")

